use std::fs;
use std::path::{Path,PathBuf};
use std::sync::Arc;
use std::time::Instant;
use echode_actions::Command;
use echode_history::{DocumentHost,write_package,recover,read_package};
use echode_model::{Project,NoteDraft,Tick,Id,AudioRef};
use echode_engine::{PlaybackCommand,playback_with_plugins,PluginRoute};
#[cfg(debug_assertions)]
#[global_allocator]
static ALLOCATOR: echode_engine::GuardAlloc = echode_engine::GuardAlloc;
fn fresh(name: &str)->PathBuf {
    let path=std::env::temp_dir().join(format!("echode-audit-20261013-{name}-{}",std::process::id()));
    fs::create_dir_all(&path).unwrap();
    write_package(&path,&Project::new()).unwrap();
    path
}
fn names(host:&DocumentHost)->Vec<String>{host.snapshot().tracks().iter().map(|t|t.name.clone()).collect()}
fn score(n:usize)->(Project,Id) {
 let (mut p,t)=Project::new().add_track("pad");
 for i in 0..n {p=p.insert_note(t,NoteDraft{pitch:60+(i%12) as u8,velocity:100,start:Tick::new(0),length:Tick::quarters(2).unwrap()}).unwrap().0;}
 (p,t)
}
fn route(id:&str,path:&str,instrument:bool)->PluginRoute{PluginRoute{clap_id:id.into(),path:path.into(),instrument}}
fn main(){
 let args:Vec<String>=std::env::args().collect();
 let mode=args[1].as_str();
 match mode {
  "journal_error"=>{
   let p=fresh(mode); let h=DocumentHost::open(&p).unwrap();
   let log=p.join("journal.jsonl"); if log.exists(){fs::remove_file(&log).unwrap();}
   fs::create_dir(&log).unwrap();
   let failed=h.perform(Command::AddTrack{name:"rejected".into()}); println!("first_error={:?}; published={:?}",failed.err().map(|e|e.to_string()),names(&h));
   fs::remove_dir(&log).unwrap();
   h.perform(Command::AddTrack{name:"accepted".into()}).unwrap();
   println!("after_success={:?}",names(&h)); h.revisions().unwrap(); drop(h);
   println!("recovered={:?}",recover(&p).unwrap().tracks().iter().map(|t|t.name.clone()).collect::<Vec<_>>());
  },
  "torn_journal"=>{
   let p=fresh(mode); drop(DocumentHost::open(&p).unwrap());
   fs::write(p.join("journal.jsonl"),b"{\"seq\":").unwrap();
   let h=DocumentHost::open(&p).unwrap(); println!("open_after_torn=true");
   h.perform(Command::AddTrack{name:"confirmed".into()}).unwrap(); println!("edit_confirmed=true");
   h.revisions().unwrap(); drop(h);
   println!("log={}",fs::read_to_string(p.join("journal.jsonl")).unwrap());
   println!("recovery={:?}",recover(&p).map(|p|p.tracks().len()).map_err(|e|e.to_string()));
  },
  "two_hosts"=>{
   let p=fresh(mode); let a=DocumentHost::open(&p).unwrap(); let b=DocumentHost::open(&p).unwrap();
   a.perform(Command::AddTrack{name:"A".into()}).unwrap(); a.revisions().unwrap();
   b.perform(Command::AddTrack{name:"B".into()}).unwrap();
   println!("both_opened=true; confirmed_A={:?}; confirmed_B={:?}",names(&a),names(&b));
   b.revisions().unwrap(); drop(b); drop(a);
   println!("recovered={:?}",recover(&p).unwrap().tracks().iter().map(|t|t.name.clone()).collect::<Vec<_>>());
  },
  "rt_replace"=>{
   let (p,_)=score(1);
   let (mut c,mut a)=playback_with_plugins(&p,48000,64,Path::new("/unused"),&[]).unwrap();
   c.command(PlaybackCommand::Play).unwrap(); let (mut l,mut r)=([0.0;64],[0.0;64]);a.render(&mut l,&mut r);
   c.replace(&p.add_track("added").0).unwrap(); a.render(&mut l,&mut r);
   println!("replacement_completed");
  },
  "rt_sort"=>{
   let mut events:Vec<_>=(0..1000).map(|i|echode_realtime::Event::note_on((i*997%1000) as u32,1,i,60,1.0)).collect();
   {let _guard=echode_engine::ForbidAlloc::enter();echode_realtime::sort_events(&mut events);}
   println!("sort_completed");
  },
  "clip_gain"=>{
   let p=fresh(mode); let wav=p.join("source.wav"); echode_cli::write_wav(&wav,48000,&vec![0.25;4096]).unwrap();
   let stored=echode_history::import_audio(&p,&wav).unwrap(); let (project,t)=Project::new().add_track("audio");
   let clip=Id::from_raw(101); let project=project.place_audio(t,clip,Id::from_raw(102),Tick::new(0),AudioRef{hash:stored.hash,sample_rate:stored.sample_rate,channels:stored.channels,frames:stored.frames}).unwrap();
   for gain in [1.0,0.0,2.0]{let changed=project.set_clip_gain(clip,gain).unwrap();let loaded=echode_audio_io::load_placed_clips(&p,&changed,48000).unwrap();let mut peak=0.0f32; echode_engine::render_offline_blocks_with_clips(&changed,48000,2048,64,&loaded,|block|{for value in block{peak=peak.max(value.abs());} Ok::<(),std::convert::Infallible>(())}).unwrap(); println!("gain={gain}; loaded_peak={}; rendered_peak={peak}",loaded[0].samples.iter().copied().fold(0.0f32,|a,b|a.max(b.abs())));}
  },
  "audio_effect"=>{
   let (p,t)=Project::new().add_track("audio");let with=p.add_clap_device(t,Id::from_raw(100),"dev.echode.test-gain").unwrap();
   let loaded=echode_engine::LoadedClip{track:t.raw(),start_sample:0,samples:Arc::from(vec![0.25;4096]),fade_in:0,fade_out:0};
   for project in [&p,&with]{
    let (mut c,mut a)=playback_with_plugins(project,48000,2048,Path::new(&args[2]),&[route("dev.echode.test-gain",&args[3],false)]).unwrap();
    let loaded=loaded.clone(); c.set_clip_loader(Arc::new(move|_,_|Ok(vec![loaded.clone()])));c.replace(project).unwrap();c.command(PlaybackCommand::Play).unwrap();
    let (mut l,mut r)=(vec![0.0;2048],vec![0.0;2048]); a.render(&mut l,&mut r);
    println!("devices={}; sample={}",project.tracks()[0].devices.len(),l[1000]);
   }
  },
  "host_deadlines"=>{
   let count:usize=args[4].parse().unwrap();let mut p=Project::new();
   for i in 0..count{let (next,t)=p.add_track(format!("track{i}"));p=next.add_clap_device(t,Id::from_raw(1000+i as u128),"dev.echode.test-gain").unwrap();}
   let (mut c,mut a)=playback_with_plugins(&p,48000,2048,Path::new(&args[2]),&[route("dev.echode.test-gain",&args[3],false)]).unwrap(); c.command(PlaybackCommand::Play).unwrap();
   let (mut l,mut r)=(vec![0.0;2048],vec![0.0;2048]);let started=Instant::now();a.render(&mut l,&mut r);println!("tracks={count}; block_ms={}; render_ms={}",2048.0/48.0,started.elapsed().as_secs_f64()*1000.0);
  },
  "event_capacity"=>{
   let (empty,t)=score(0);let empty=empty.add_clap_device(t,Id::from_raw(200),"dev.echode.audit-probe").unwrap();
   let mut changed=empty.clone();for pitch in [60,64,67]{changed=changed.insert_note(t,NoteDraft{pitch,velocity:100,start:Tick::new(0),length:Tick::quarters(2).unwrap()}).unwrap().0;}
   for initial in [&empty,&changed]{
    let (mut c,mut a)=playback_with_plugins(initial,48000,2048,Path::new(&args[2]),&[route("dev.echode.audit-probe",&args[3],true)]).unwrap();
    c.replace(&changed).unwrap();c.command(PlaybackCommand::Play).unwrap();let (mut l,mut r)=(vec![0.0;2048],vec![0.0;2048]);a.render(&mut l,&mut r);println!("initial_notes={}; sample={}",if initial==&empty{0}else{3},l[1000]);
   }
  },
  "plugin_seek"|"plugin_delete"=>{
   let (p,t)=score(1);let p=p.add_clap_device(t,Id::from_raw(200),"dev.echode.audit-probe").unwrap();
   let (mut c,mut a)=playback_with_plugins(&p,48000,2048,Path::new(&args[2]),&[route("dev.echode.audit-probe",&args[3],true)]).unwrap();
   c.command(PlaybackCommand::Play).unwrap();let (mut l,mut r)=(vec![0.0;2048],vec![0.0;2048]);a.render(&mut l,&mut r);println!("before={}",l[1000]);
   if mode=="plugin_seek"{c.command(PlaybackCommand::Locate(100000)).unwrap();}
   else{let note=p.contents()[0].notes[0].id; c.replace(&p.delete_note(t,note).unwrap()).unwrap();}
   a.render(&mut l,&mut r);println!("after={}",l[1000]);
  },
  "offline_plugin"=>{
   let (p,t)=score(1);let p=p.add_clap_device(t,Id::from_raw(200),"dev.echode.audit-probe").unwrap();
   let (mut c,mut a)=playback_with_plugins(&p,48000,2048,Path::new(&args[2]),&[route("dev.echode.audit-probe",&args[3],true)]).unwrap();
   c.command(PlaybackCommand::Play).unwrap();let (mut l,mut r)=(vec![0.0;2048],vec![0.0;2048]);a.render(&mut l,&mut r);
   let mut offline=vec![0.0;4096];echode_engine::render_offline(&p,48000,2048,&mut offline).unwrap();println!("live_sample={}; offline_sample={}",l[1000],offline[2000]);
  },
  "stale_export"=>{
   let path=fresh(mode); let h=DocumentHost::open(&path).unwrap();
   fs::create_dir(path.join("save.pending")).unwrap();
   let action=h.perform(Command::AddTrack{name:"confirmed".into()}).unwrap();
   let echode_actions::Action::AddTrack{id:track,..}=action else{panic!("track")};h.perform(Command::InsertNote{track,draft:NoteDraft{pitch:60,velocity:100,start:Tick::new(0),length:Tick::quarters(2).unwrap()}}).unwrap(); println!("published={:?}",names(&h)); h.revisions().unwrap();
   println!("read_package_tracks={}; recovered_tracks={}",read_package(&path).unwrap().tracks().len(),recover(&path).unwrap().tracks().len()); let wav=path.join("stale.wav");echode_cli::render_to_wav(&path,&wav,48000,Some(2048)).unwrap();let bytes=fs::read(wav).unwrap();let mut expected=vec![0.0;4096];echode_engine::render_offline(&recover(&path).unwrap(),48000,2048,&mut expected).unwrap();println!("wav_all_zero={}; recovered_audio_peak={}",bytes[44..].iter().all(|b|*b==0),expected.iter().copied().fold(0.0f32,|a,b|a.max(b.abs())));
  },

  "torn_utf8"=>{
   let p=fresh(mode);drop(DocumentHost::open(&p).unwrap());fs::write(p.join("journal.jsonl"),[b'{',0xff]).unwrap();
   println!("recover={:?}",recover(&p).map(|p|p.tracks().len()).map_err(|e|e.to_string()));
  },
  "socket_file"=>{
   let p=fresh(mode);let path=p.join("valuable.json");fs::write(&path,b"valuable").unwrap();
   let result=echode_api::bind_socket(&path);println!("bound={}; original_preserved={}",result.is_ok(),fs::read(&path).ok()==Some(b"valuable".to_vec()));
  },
  _=>panic!("unknown mode")
 }
}

