use clack_plugin::prelude::*;
use clack_plugin::events::spaces::CoreEventSpace;
pub struct Probe;
impl Plugin for Probe {
 type AudioProcessor<'a>=Processor;
 type Shared<'a>=();
 type MainThread<'a>=();
}
impl DefaultPluginFactory for Probe {
 fn get_descriptor()->PluginDescriptor{
  PluginDescriptor::new("dev.echode.audit-probe","Echode Audit Probe").with_features([c"instrument"])
 }
 fn new_shared(_host:HostSharedHandle<'_>)->Result<(),PluginError>{Ok(())}
 fn new_main_thread<'a>(_host:HostMainThreadHandle<'a>,_shared:&'a ())->Result<(),PluginError>{Ok(())}
}
pub struct Processor{active:i32}
impl<'a> PluginAudioProcessor<'a,(),()> for Processor {
 fn activate(_host:HostAudioProcessorHandle<'a>,_main:&(),_shared:&'a (),_config:PluginAudioConfiguration)->Result<Self,PluginError>{Ok(Self{active:0})}
 fn process(&mut self,_process:Process,mut audio:Audio,events:Events)->Result<ProcessStatus,PluginError>{
  for event in events.input.iter(){
   match event.as_core_event(){
    Some(CoreEventSpace::NoteOn(_))=>self.active+=1,
    Some(CoreEventSpace::NoteOff(_))=>self.active-=1,
    Some(CoreEventSpace::NoteChoke(_))=>self.active=0,
    _=>{}
   }
  }
  for mut pair in &mut audio {
   if let Some(channels)=pair.channels()?.into_f32(){
    for channel in channels{
     match channel{
      ChannelPair::InputOnly(_)=>{},
      ChannelPair::OutputOnly(out)=>out.fill(self.active as f32),
      ChannelPair::InputOutput(_,out)=>out.fill(self.active as f32),
      ChannelPair::InPlace(out)=>out.fill(self.active as f32),
     }
    }
   }
  }
  Ok(ProcessStatus::Continue)
 }
}
clack_export_entry!(SinglePluginEntry<Probe>);
